def process_type_info(self, info: TypeInfo | None) -> None:
    if info is None:
        return
    self.fixup_type(info.declared_metaclass)
    self.fixup_type(info.metaclass_type)
    for target in info._promote:
        self.fixup_type(target)
    self.fixup_type(info.tuple_type)
    self.fixup_type(info.typeddict_type)
    if info.special_alias:
        self.fixup_type(info.special_alias.target)
    info.defn.info = self.fixup(info)
    replace_nodes_in_symbol_table(info.names, self.replacements)
    for i, item in enumerate(info.mro):
        info.mro[i] = self.fixup(info.mro[i])
    for i, base in enumerate(info.bases):
        self.fixup_type(info.bases[i])

def transform_op_expr(builder: IRBuilder, expr: OpExpr) -> Value:
    if expr.op in ("and", "or"):
        return builder.shortcircuit_expr(expr)

    # Special case for string formatting
    if expr.op == "%" and isinstance(expr.left, (StrExpr, BytesExpr)):
        ret = translate_printf_style_formatting(builder, expr.left, expr.right)
        if ret is not None:
            return ret

    folded = try_constant_fold(builder, expr)
    if folded:
        return folded

    borrow_left = False
    borrow_right = False

    ltype = builder.node_type(expr.left)
    rtype = builder.node_type(expr.right)

    # Special case some int ops to allow borrowing operands.
    if is_int_rprimitive(ltype) and is_int_rprimitive(rtype):
        if expr.op == "//":
            expr = try_optimize_int_floor_divide(builder, expr)
        if expr.op in int_borrow_friendly_op:
            borrow_left = is_borrow_friendly_expr(builder, expr.right)
            borrow_right = True
    elif is_fixed_width_rtype(ltype) and is_fixed_width_rtype(rtype):
        borrow_left = is_borrow_friendly_expr(builder, expr.right)
        borrow_right = True

    left = builder.accept(expr.left, can_borrow=borrow_left)
    right = builder.accept(expr.right, can_borrow=borrow_right)
    return builder.binary_op(left, right, expr.op, expr.line)

def is_optional(self) -> bool:
    item_type = self.item_type
    if isinstance(item_type, RUnion):
        return True
    elif isinstance(item_type, RVec):
        return item_type.is_optional()
    return False

def explain_metaclass_conflict(self) -> str | None:
    # Compare to logic in calculate_metaclass_type
    declared = self.declared_metaclass
    if declared is not None and not declared.type.has_base("builtins.type"):
        return None
    if self._fullname == "builtins.type":
        return None

    winner = declared
    if declared is None:
        resolution_steps = []
    else:
        resolution_steps = [f'"{declared.type.fullname}" (metaclass of "{self.fullname}")']
    for super_class in self.mro[1:]:
        super_meta = super_class.declared_metaclass
        if super_meta is None or super_meta.type is None:
            continue
        if winner is None:
            winner = super_meta
            resolution_steps.append(
                f'"{winner.type.fullname}" (metaclass of "{super_class.fullname}")'
            )
            continue
        if winner.type.has_base(super_meta.type.fullname):
            continue
        if super_meta.type.has_base(winner.type.fullname):
            winner = super_meta
            resolution_steps.append(
                f'"{winner.type.fullname}" (metaclass of "{super_class.fullname}")'
            )
            continue
        # metaclass conflict
        conflict = f'"{super_meta.type.fullname}" (metaclass of "{super_class.fullname}")'
        return f"{' > '.join(resolution_steps)} conflicts with {conflict}"

    return None

def visit_any(self, t: AnyType) -> str:
    if t.missing_import_name:
        return t.missing_import_name
    else:
        return "Any"

def reduce_and_conditional_type_maps(ms: list[TypeMap], *, use_meet: bool) -> TypeMap:
    """Reduces a list of TypeMaps into a single TypeMap by "and"-ing them together."""
    if len(ms) == 0:
        return {}
    if len(ms) == 1:
        return ms[0]
    result = ms[0]
    for m in ms[1:]:
        if not m:
            continue  # this is a micro-optimisation
        result = and_conditional_maps(result, m, use_meet=use_meet)
    return result

def parse_section(
    prefix: str,
    template: Options,
    set_strict_flags: Callable[[], None],
    section: Mapping[str, Any],
    config_types: dict[str, Any],
    stderr: TextIO = sys.stderr,
) -> tuple[dict[str, object], dict[str, str]]:
    """Parse one section of a config file.

    Returns a dict of option values encountered, and a dict of report directories.
    """
    results: dict[str, object] = {}
    report_dirs: dict[str, str] = {}

    # Because these fields exist on Options, without proactive checking, we would accept them
    # and crash later
    invalid_options = {
        "enabled_error_codes": "enable_error_code",
        "disabled_error_codes": "disable_error_code",
    }

    for key in section:
        invert = False
        # Here we use `key` for original config section key, and `options_key` for
        # the corresponding Options attribute.
        options_key = key
        # Match aliasing for deprecated config option name.
        if options_key == "allow_redefinition_new":
            options_key = "allow_redefinition"
        if key in config_types:
            ct = config_types[key]
        elif key in invalid_options:
            print(
                f"{prefix}Unrecognized option: {key} = {section[key]}"
                f" (did you mean {invalid_options[key]}?)",
                file=stderr,
            )
            continue
        else:
            dv = getattr(template, options_key, None)
            if dv is None:
                if key.endswith("_report"):
                    report_type = key[:-7].replace("_", "-")
                    if report_type in defaults.REPORTER_NAMES:
                        report_dirs[report_type] = str(section[key])
                    else:
                        print(f"{prefix}Unrecognized report type: {key}", file=stderr)
                    continue
                if key.startswith("x_"):
                    pass  # Don't complain about `x_blah` flags
                elif key.startswith("no_") and hasattr(template, options_key[3:]):
                    options_key = options_key[3:]
                    invert = True
                elif key.startswith("allow") and hasattr(template, "dis" + options_key):
                    options_key = "dis" + options_key
                    invert = True
                elif key.startswith("disallow") and hasattr(template, options_key[3:]):
                    options_key = options_key[3:]
                    invert = True
                elif key.startswith("show_") and hasattr(template, "hide_" + options_key[5:]):
                    options_key = "hide_" + options_key[5:]
                    invert = True
                elif key == "strict":
                    pass  # Special handling below
                else:
                    print(f"{prefix}Unrecognized option: {key} = {section[key]}", file=stderr)
                if invert:
                    dv = getattr(template, options_key, None)
                else:
                    continue
            ct = type(dv) if dv is not None else None
        v: Any = None
        try:
            if ct is bool:
                if isinstance(section, dict):
                    v = convert_to_boolean(section.get(key))
                else:
                    v = section.getboolean(key)  # type: ignore[attr-defined]  # Until better stub
                if invert:
                    v = not v
            elif callable(ct):
                if invert:
                    print(f"{prefix}Can not invert non-boolean key {options_key}", file=stderr)
                    continue
                try:
                    v = ct(section.get(key))
                except VersionTypeError as err_version:
                    print(f"{prefix}{key}: {err_version}", file=stderr)
                    v = err_version.fallback
                except argparse.ArgumentTypeError as err:
                    print(f"{prefix}{key}: {err}", file=stderr)
                    continue

def no_variant_matches_arguments(
    self,
    overload: Overloaded,
    arg_types: list[Type],
    context: Context,
    *,
    arg_names: Sequence[str | None] | None,
    arg_kinds: list[ArgKind] | None = None,
    code: ErrorCode | None = None,
) -> None:
    code = code or codes.CALL_OVERLOAD
    name = callable_name(overload)
    if name:
        name_str = f" of {name}"
        for_func = f" for overloaded function {name}"
    else:
        name_str = ""
        for_func = ""

    # For keyword argument errors
    unexpected_kwargs: list[tuple[str, Type]] = []
    if arg_names is not None and arg_kinds is not None:
        all_valid_kwargs: set[str] = set()
        for item in overload.items:
            for i, arg_name in enumerate(item.arg_names):
                if arg_name is not None and item.arg_kinds[i] != ARG_STAR:
                    all_valid_kwargs.add(arg_name)
            if item.is_kw_arg:
                all_valid_kwargs.clear()
                break

        if all_valid_kwargs:
            for i, (arg_name, arg_kind) in enumerate(zip(arg_names, arg_kinds)):
                if arg_kind == ARG_NAMED and arg_name is not None:
                    if arg_name not in all_valid_kwargs:
                        unexpected_kwargs.append((arg_name, arg_types[i]))

    if unexpected_kwargs:
        all_kwargs_confident = True
        kwargs_with_suggestions: list[tuple[str, list[str]]] = []
        kwargs_without_suggestions: list[str] = []

        # Find suggestions for each unexpected kwarg, prioritizing type-matching args
        for kwarg_name, kwarg_type in unexpected_kwargs:
            matching_type_args: list[str] = []
            not_matching_type_args: list[str] = []
            has_matching_variant = False

            for item in overload.items:
                item_has_type_match = False
                for i, formal_type in enumerate(item.arg_types):
                    formal_name = item.arg_names[i]
                    if formal_name is not None and item.arg_kinds[i] != ARG_STAR:
                        if is_subtype(kwarg_type, formal_type):
                            if formal_name not in matching_type_args:
                                matching_type_args.append(formal_name)
                            item_has_type_match = True
                        elif formal_name not in not_matching_type_args:
                            not_matching_type_args.append(formal_name)
                if item_has_type_match:
                    has_matching_variant = True

            if not self.prefer_simple_messages():
                matches = best_matches(kwarg_name, matching_type_args, n=3)
                if not matches:
                    matches = best_matches(kwarg_name, not_matching_type_args, n=3)
            else:
                matches = []

            if matches:
                kwargs_with_suggestions.append((kwarg_name, matches))
            else:
                kwargs_without_suggestions.append(kwarg_name)

            if not has_matching_variant:
                all_kwargs_confident = False

        for kwarg_name, matches in kwargs_with_suggestions:
            self.fail(
                f'Unexpected keyword argument "{kwarg_name}"'
                f"{for_func}; did you mean {pretty_seq(matches, 'or')}?",
                context,
                code=code,
            )

        if kwargs_without_suggestions:
            if len(kwargs_without_suggestions) == 1:
                self.fail(
                    f'Unexpected keyword argument "{kwargs_without_suggestions[0]}"{for_func}',
                    context,
                    code=code,
                )

def get_dynamic_class_hook(
    self, fullname: str
) -> Callable[[DynamicClassDefContext], None] | None:
    return self._find_hook(lambda plugin: plugin.get_dynamic_class_hook(fullname))

@verify.register(nodes.OverloadedFuncDef)
def verify_overloadedfuncdef(
    stub: nodes.OverloadedFuncDef, runtime: MaybeMissing[Any], object_path: list[str]
) -> Iterator[Error]:
    # TODO: support `@type_check_only` decorator
    if isinstance(runtime, Missing):
        yield Error(object_path, "is not present at runtime", stub, runtime)
        return

    if stub.is_property:
        # Any property with a setter is represented as an OverloadedFuncDef
        if is_read_only_property(runtime):
            yield Error(object_path, "is read-only at runtime but not in the stub", stub, runtime)
        return

    if not is_probably_a_function(runtime):
        yield Error(object_path, "is not a function", stub, runtime)
        if not callable(runtime):
            return

    # mypy doesn't allow overloads where one overload is abstract but another isn't,
    # so it should be okay to just check whether the first overload is abstract or not.
    #
    # TODO: Mypy *does* allow properties where e.g. the getter is abstract but the setter is not;
    # and any property with a setter is represented as an OverloadedFuncDef internally;
    # not sure exactly what (if anything) we should do about that.
    first_part = stub.items[0]
    if isinstance(first_part, nodes.Decorator) and first_part.is_overload:
        for msg in _verify_abstract_status(first_part.func, runtime):
            yield Error(object_path, msg, stub, runtime)

    # Look the object up statically, to avoid binding by the descriptor protocol
    static_runtime = _static_lookup_runtime(object_path)

    for message in _verify_static_class_methods(stub, runtime, static_runtime, object_path):
        yield Error(object_path, "is inconsistent, " + message, stub, runtime)

    # TODO: Should call _verify_final_method here,
    # but overloaded final methods in stubs cause a stubtest crash: see #14950

    signature = safe_inspect_signature(runtime)
    if not signature:
        return

    stub_sig = Signature.from_overloadedfuncdef(stub)
    runtime_sig = Signature.from_inspect_signature(signature)

    for message in _verify_signature(
        stub_sig,
        runtime_sig,
        function_name=stub.name,
        warn_runtime_is_object_init=runtime is object.__init__,
    ):
        # TODO: This is a little hacky, but the addition here is super useful
        if "has a default value of type" in message:
            message += (
                ". This is often caused by overloads failing to account for explicitly passing "
                "in the default value."
            )
        yield Error(
            object_path,
            "is inconsistent, " + message,
            stub,
            runtime,
            stub_desc=(str(stub.type)) + f"\nInferred signature: {stub_sig}",
            runtime_desc="def " + str(signature),
        )

